// Slice 125 — seller status tracker + offer receipt. The seller
// follows their submission on a private link (/track/<token>)
// with no login. The token is an unguessable uuid generated by
// the database (leads.tracker_token); the tracker shows ONLY the
// seller's own progress, the offer receipt when an offer exists,
// and the closing date — never contact details, never other
// leads. The offer receipt is built ONLY from numbers the
// wholesaler actually entered (their own comps, repair estimate,
// resale costs) or the county roll returned; a missing piece
// reads "not provided" instead of being invented. No comp is
// ever fabricated, and no figure is computed for the wholesaler.

import type { Lead, SellerStatus } from './leads';
import { SELLER_STATUSES } from './leads';

export const TRACKER_STEPS: { key: SellerStatus; label: string }[] = [
  { key: 'received', label: 'Received' },
  { key: 'reviewed', label: 'Reviewed' },
  { key: 'offer_made', label: 'Offer made' },
  { key: 'closing_scheduled', label: 'Closing' },
  { key: 'closed', label: 'Closed' },
];

// Index of the furthest step reached. 'closing_scheduled' and
// 'closed' both light the Closing step; 'closed' marks it done.
export function trackerStepIndex(status: SellerStatus | null | undefined): number {
  switch (status) {
    case 'reviewed': return 1;
    case 'offer_made': return 2;
    case 'closing_scheduled': return 3;
    case 'closed': return 4;
    default: return 0;
  }
}

export function isValidSellerStatus(v: string): v is SellerStatus {
  return (SELLER_STATUSES as string[]).includes(v);
}

// --- Offer receipt -------------------------------------------------------

export interface OfferReceiptLine {
  label: string;
  // A formatted value, or null when the wholesaler did not provide it.
  value: string | null;
}

export interface OfferReceipt {
  amount: number;
  lines: OfferReceiptLine[];
  note: string | null;
  askingPrice: number | null;
}

const money = (n: number): string => `$${Math.round(n).toLocaleString('en-US')}`;

export function buildOfferReceipt(lead: Lead): OfferReceipt | null {
  if (lead.offer_amount == null || !Number.isFinite(lead.offer_amount)) return null;
  const compLow = lead.offer_comp_low;
  const compHigh = lead.offer_comp_high;
  const comps =
    compLow != null && compHigh != null
      ? `${money(compLow)} – ${money(compHigh)}`
      : compLow != null
        ? `${money(compLow)}+`
        : compHigh != null
          ? `up to ${money(compHigh)}`
          : null;
  return {
    amount: lead.offer_amount,
    lines: [
      { label: 'comps', value: comps },
      { label: 'repairs', value: lead.offer_repairs != null ? money(lead.offer_repairs) : null },
      { label: 'resale', value: lead.offer_resale_costs != null ? money(lead.offer_resale_costs) : null },
    ],
    note: lead.offer_note?.trim() || null,
    askingPrice: lead.asking_price ?? null,
  };
}

// --- Public tracker fetch (no login) ------------------------------------

export interface PublicTrackerLead {
  property_address: string;
  city: string | null;
  state: string | null;
  seller_status: SellerStatus;
  preferred_closing_date: string | null;
  company: string;
  slug: string;
  receipt: OfferReceipt | null;
}

export async function fetchTracker(token: string): Promise<PublicTrackerLead | null> {
  const t = token.trim();
  if (!t) return null;
  try {
    const res = await fetch(`/api/track/${encodeURIComponent(t)}`);
    if (!res.ok) return null;
    const json = (await res.json().catch(() => null)) as { lead?: Record<string, unknown> } | null;
    if (!json || !json.lead) return null;
    const l = json.lead as Record<string, unknown>;
    const status = typeof l.seller_status === 'string' && isValidSellerStatus(l.seller_status) ? l.seller_status : 'received';
    const rawLead: Lead = {
      property_address: String(l.property_address || ''),
      status: 'new',
      offer_amount: typeof l.offer_amount === 'number' ? l.offer_amount : null,
      offer_comp_low: typeof l.offer_comp_low === 'number' ? l.offer_comp_low : null,
      offer_comp_high: typeof l.offer_comp_high === 'number' ? l.offer_comp_high : null,
      offer_repairs: typeof l.offer_repairs === 'number' ? l.offer_repairs : null,
      offer_resale_costs: typeof l.offer_resale_costs === 'number' ? l.offer_resale_costs : null,
      offer_note: typeof l.offer_note === 'string' ? l.offer_note : null,
      asking_price: typeof l.asking_price === 'number' ? l.asking_price : null,
    };
    return {
      property_address: String(l.property_address || ''),
      city: typeof l.city === 'string' ? l.city : null,
      state: typeof l.state === 'string' ? l.state : null,
      seller_status: status,
      preferred_closing_date: typeof l.preferred_closing_date === 'string' ? l.preferred_closing_date : null,
      company: typeof l.company === 'string' ? l.company : '',
      slug: typeof l.slug === 'string' ? l.slug : '',
      receipt: buildOfferReceipt(rawLead),
    };
  } catch {
    return null;
  }
}

// After a seller submits, the thank-you screen offers the private
// tracking link. The token lives server-side, so this route hands
// it out only for a fresh seller-page submission (same 2-hour
// freshness window as the seller-photo route) — never for an old
// lead, and never without the matching page slug.
export async function fetchTrackToken(leadId: string, slug: string): Promise<string | null> {
  try {
    const res = await fetch('/api/track-token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ lead_id: leadId, slug }),
    });
    if (!res.ok) return null;
    const json = (await res.json().catch(() => null)) as { token?: string } | null;
    return typeof json?.token === 'string' && json.token ? json.token : null;
  } catch {
    return null;
  }
}
